import fs from 'node:fs';
const env = Object.fromEntries(fs.readFileSync('.env', 'utf8').split('\n')
  .filter(l => l && !l.startsWith('#')).map(l => l.split('=')));
if (!env.GEMINI_API_KEY) { console.error('Error: GEMINI_API_KEY is missing'); process.exit(1); }
